#!/bin/sh
ROLE=$(redis-cli -h $(hostname) -p ${REDIS_PORT}  -a "${REDIS_PASSWORD}"  info replication | awk -F: '/role:master/ {print "master"}')

if [ "$ROLE" = "master" ]; then
    BEST_SLAVE=$(redis-cli -h $(hostname) -p ${REDIS_PORT}  -a "${REDIS_PASSWORD}"  info replication | awk -F: '
        BEGIN { maxOffset = -1; bestSlave = "" }
        /slave[0-9]+:ip/ {
            split($2, a, ",");
            split(a[1], ip_arr, "=");
            split(a[4], offset_arr, "=");
            ip = ip_arr[2];
            offset = offset_arr[2] + 0;
            if (offset > maxOffset) {
                maxOffset = offset;
                bestSlave = ip;
            }
        }
        END { print bestSlave }
    ')

    if [ -n "$BEST_SLAVE" ]; then
        redis-cli -h "$BEST_SLAVE" -p ${REDIS_PORT}  -a "${REDIS_PASSWORD}"  cluster failover
    fi
fi

